export type Input = { first: u64[], second: u64[] }

export type Output = Input

export default function (in: owned Input): Output {
 const first = in.first.reverse()[0]

 return in
}

export type Input = { first: u64[], second: u64[] }

export type Output = u64[]

export default function (in: owned Input): Output {
 const first = in.first.reverse()[0]

 return in.first.sort()[0]
}

export type Input = bool

export type Output = u64[]

export default function (in: Input): Output {
 const source = { first: [3, 1], second: [4, 2] }

 if (in) { const first = source.first.reverse()[0] }

 return source.first
}

export type Input = u64[][]

export type Output = u64[]

export default function (in: owned Input): Output {
 const first = in[0].reverse()[0]

 return in[1]
}

export type Input = { first: u64[], second: u64[] }

export type Output = u64[]

export default function (in: Input): Output {
 return in.first.reverse()[0]
}

import borrow from "./borrow.zx"

export type Input = void

export type Output = u64[]

export default function (in: Input): Output {
 const source = { first: [3, 1], second: [4, 2] }
 const first = borrow(source.first)
 const alias = source

 return source.second.reverse()[0]
}

export type Input = void

export type Output = u64[]

export default function (in: Input): Output {
 const source = { first: [3, 1], second: [4, 2] }
 const next = { ...source, second: source.first }
 const first = next.first.reverse()[0]

 return next.second
}
